const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET;
if (!secret) throw new Error('Missing LENDLOOP_HMAC_SECRET');
const input = $input.first().json;
let payload = input.body ?? input;
if (typeof payload === 'string') payload = JSON.parse(payload);
const headers = input.headers ?? {};
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const signature = String(headers['x-lendloop-signature'] ?? '').replace(/^v1=/, '');
if (!/^\d+$/.test(timestamp) || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) {
  throw new Error('Rejected stale or invalid timestamp');
}
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${JSON.stringify(payload)}`).digest('hex');
const suppliedBytes = Buffer.from(signature, 'hex');
const expectedBytes = Buffer.from(expected, 'hex');
if (suppliedBytes.length !== expectedBytes.length || !crypto.timingSafeEqual(suppliedBytes, expectedBytes)) {
  throw new Error('Rejected invalid LendLoop HMAC signature');
}
if (!payload.eventId || !payload.requestId || !payload.recipientEmail) {
  throw new Error('Request event is missing required notification fields');
}
return [{ json: payload }];

const event = $input.first().json;
console.log('[LendLoop mock notification]', JSON.stringify({
  eventId: event.eventId,
  eventType: event.eventType,
  to: event.recipientEmail,
  recipientName: event.recipientName,
  toolName: event.toolName,
  status: event.status,
  startAt: event.startAt,
  endAt: event.endAt
}));
return [{ json: { accepted: true, eventId: event.eventId } }];
